contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an amount to forward to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe pre-call values
        address preOwner = c.owner();
        uint preCbal = address(c).balance;
        uint preThis = address(this).balance;

        // perform the call and catch if it reverts
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-call values
        address postOwner = c.owner();
        uint postCbal = address(c).balance;
        uint postThis = address(this).balance;

        // If owner were ever changed by go it would break the rule; also if call succeeded then any Ether remaining in C must have been forwarded back to this contract (so this contract's balance increases by exactly preCbal - postCbal)
        assert(postOwner == preOwner && (reverted || postThis - preThis == preCbal - postCbal));
    }

    receive() external payable { }
}
